                } else {
                    // i == node_id, j != node_id
                    // pre.combiner[j] = post.combiner[j] since only node_id changed
                    // pre.combiner[node_id] = Appending { cur_idx, tail }
                    // post.combiner[node_id] = Appending { cur_idx + 1, tail }
                    let pre_j = pre.combiner[j];
                    let pre_node_id = pre.combiner[node_id];
                    let post_node_id = post.combiner[node_id];

                    // By invariant on pre state, pre_node_id.no_overlap_with(pre_j)
                    // We need to show post_node_id.no_overlap_with(pre_j)
                    // The no_overlap_with only depends on cur_idx and tail for Appending state
                    // Since cur_idx + 1 > cur_idx, if pre_node_id was after pre_j, so is post_node_id
                    // And if pre_node_id was before pre_j (tail <= ...), same holds for post_node_id
                }
