    fn advance_head_next_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

    #[inductive(advance_head_abort)]
    fn advance_head_abort_inductive(pre: Self, post: Self, node_id: NodeId) { admit(); }

